import{_ as o,o as n,c as a,a0 as c}from"./chunks/framework.DhQjJcnt.js";const m=JSON.parse('{"title":"Skill: /module","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/module.md","filePath":"references/skills/module.md"}'),l={name:"references/skills/module.md"};function t(i,e,d,u,s,h){return n(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="skill-module" tabindex="-1">Skill: <code>/module</code> <a class="header-anchor" href="#skill-module" aria-label="Permalink to &quot;Skill: `/module`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>module</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/module &lt;CMP-ID&gt;</code> (Ví dụ: <code>/module CMP-ADM-000</code>)</li><li>Có thể dùng kèm tên thư mục Surface: <code>/module &quot;Customer App&quot; CMP-123</code></li><li>Khảo cổ mã nguồn cũ: <code>/legacy /module</code></li><li>Chia sẻ tài nguyên chung của 1 Module: <code>/module &lt;CMP-ID&gt; common</code></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Nhận diện CMP ID do người dùng cung cấp. Agent sẽ tự động phân giải (Resolve Target) xem Module đó đang nằm ở Surface nào bằng <code>flowgrid_docs_route</code> hoặc glob search.</li><li>Định nghĩa các cụm chức năng (Clusters), quy trình hoặc API nội bộ trong Module đó.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Khởi tạo thư mục Module tại <code>surfaces/&lt;Surface&gt;/&lt;CMP-ID&gt;/</code>.</li><li>Sinh ra file tài liệu gốc của Module: <code>surfaces/&lt;Surface&gt;/&lt;CMP-ID&gt;/&lt;CMP-ID&gt;.md</code>.</li><li><strong>Luật về ID Phân cấp (Numeric Hierarchical IDs):</strong> Mọi thư mục con đại diện cho các tính năng/màn hình nhỏ bên trong Module BẮT BUỘC phải dùng định dạng ID thuần số (Ví dụ: <code>01/</code>, <code>01/01/02/</code>). TUYỆT ĐỐI KHÔNG dùng tên dạng chữ (textual slug) để đặt tên thư mục con của Module.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Quản lý cấp độ chức năng lớn (Business Modules) - thường là các cụm màn hình hoặc một nhóm quy trình nghiệp vụ gom chung lại (Ví dụ: Module Quản lý Người dùng, Module Thanh toán).</li><li>Hỗ trợ tạo thư mục <code>common/</code> cục bộ cho Module đó. Ví dụ: Nếu một vài hàm tiện ích (utils) hoặc file YAML chỉ xài chung quanh quẩn trong <code>CMP-123</code>, ta sẽ bỏ vào <code>surfaces/&lt;Surface&gt;/CMP-123/common/</code> thay vì quăng ra ngoài <code>surfaces/common</code> gây rác hệ thống.</li><li>VitePress/Publish sẽ đọc các file <code>[CMP-ID].md</code> này và dùng Mã tài liệu (vd <code>SPEC-PORTAL-AUTH-00</code>) làm Text hiển thị trên Menu.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Được kích hoạt/điều phối bởi <code>/architecture</code>.</li><li>Nằm dưới cấp của <code>/surfaces</code>.</li><li>Chứa bên trong nó là vô số các <code>/spec</code> (Đặc tả màn hình chi tiết).</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/module</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const g=o(l,[["render",t]]);export{m as __pageData,g as default};
